// Package fixturejson reads and writes JSON in the exact byte format the
// committed fixtures were derived in, so that a fixture regenerated by the
// anonymisers in shared/scripts is a no-op diff.
//
// encoding/json cannot do that on its own, for four reasons, each of which
// moves bytes in a committed file:
//
//   - Object keys keep DOCUMENT order (and a rewritten row keeps its column
//     order, a new column going last). map[string]any sorts them.
//   - An integer and a float stay apart: `5` and `5.0` are different values
//     and print differently. A JSON number is a float when its text has a
//     `.`, an `e` or an `E`, and an integer otherwise.
//   - A float prints as the shortest text that round-trips, always with a
//     decimal point or an exponent (`125.0`, not `125`), switching to an
//     exponent below 1e-4 and from 1e16 up (`1e-05`, `1e+16`).
//   - Strings escape only `"`, `\` and control characters, `\n` style where
//     one exists and `\u00XX` (lower-case hex) otherwise; with ascii set,
//     everything outside space..`~` is escaped too, astral runes as a
//     surrogate pair.
//
// A duplicate key keeps its FIRST position and its LAST value.
package fixturejson

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"math"
	"math/big"
	"sort"
	"strconv"
	"strings"
	"unicode/utf16"
)

// Kind is a JSON value's kind, with integers and floats kept apart.
type Kind int

// The kinds.
const (
	Null Kind = iota
	Bool
	Int
	Float
	String
	Array
	Object
)

// Value is one JSON value. Only the field its Kind names is meaningful.
type Value struct {
	Kind Kind
	B    bool
	I    string // Int: canonical decimal text, any size
	F    float64
	S    string
	A    []*Value
	O    *Obj
}

// Obj is an object whose keys keep their insertion order.
type Obj struct {
	keys []string
	vals map[string]*Value
}

// NewObj returns an empty object.
func NewObj() *Obj { return &Obj{vals: map[string]*Value{}} }

// Keys returns the keys in order.
func (o *Obj) Keys() []string { return o.keys }

// Len is the number of keys.
func (o *Obj) Len() int { return len(o.keys) }

// Get returns the value at k and whether k is present.
func (o *Obj) Get(k string) (*Value, bool) {
	v, ok := o.vals[k]
	return v, ok
}

// GetOrNull returns the value at k, or a null when k is absent.
func (o *Obj) GetOrNull(k string) *Value {
	if v, ok := o.vals[k]; ok {
		return v
	}
	return NullValue()
}

// Set stores v at k: in place when k is present, appended last when not.
func (o *Obj) Set(k string, v *Value) {
	if _, ok := o.vals[k]; !ok {
		o.keys = append(o.keys, k)
	}
	o.vals[k] = v
}

// Delete removes k, keeping the other keys' order.
func (o *Obj) Delete(k string) {
	if _, ok := o.vals[k]; !ok {
		return
	}
	delete(o.vals, k)
	for i, key := range o.keys {
		if key == k {
			o.keys = append(o.keys[:i:i], o.keys[i+1:]...)
			return
		}
	}
}

// NullValue is a JSON null.
func NullValue() *Value { return &Value{Kind: Null} }

// Str is a JSON string.
func Str(s string) *Value { return &Value{Kind: String, S: s} }

// Num is a JSON float.
func Num(f float64) *Value { return &Value{Kind: Float, F: f} }

// IntValue is a JSON integer.
func IntValue(i int64) *Value { return &Value{Kind: Int, I: strconv.FormatInt(i, 10)} }

// Arr is a JSON array.
func Arr(vs ...*Value) *Value { return &Value{Kind: Array, A: vs} }

// ObjValue wraps o as a value.
func ObjValue(o *Obj) *Value { return &Value{Kind: Object, O: o} }

// IsNull reports a null (or a nil pointer, which stands for one).
func (v *Value) IsNull() bool { return v == nil || v.Kind == Null }

// IsEmptyOrNull reports a null or the empty string.
func (v *Value) IsEmptyOrNull() bool {
	return v.IsNull() || (v.Kind == String && v.S == "")
}

// Truthy is the usual truth of a decoded value: false for null, false, zero,
// the empty string and an empty array or object; true otherwise (NaN too).
func (v *Value) Truthy() bool {
	if v == nil {
		return false
	}
	switch v.Kind {
	case Null:
		return false
	case Bool:
		return v.B
	case Int:
		return v.I != "0"
	case Float:
		return v.F != 0
	case String:
		return v.S != ""
	case Array:
		return len(v.A) > 0
	case Object:
		return v.O.Len() > 0
	}
	return false
}

// Float64 is a number's value as a float64 (true and false read as 1 and 0).
func (v *Value) Float64() (float64, error) {
	switch v.Kind {
	case Float:
		return v.F, nil
	case Int:
		f, err := strconv.ParseFloat(v.I, 64)
		if err != nil && !errors.Is(err, strconv.ErrRange) {
			return 0, err
		}
		return f, nil
	case Bool:
		if v.B {
			return 1, nil
		}
		return 0, nil
	}
	return 0, fmt.Errorf("not a number: %s", Compact(v, false))
}

// Text is a scalar's plain text: a string as itself, a number as it prints,
// a boolean as True/False and null as None — the spelling the committed
// fixtures' hashed fields were keyed on.
func (v *Value) Text() (string, error) {
	switch v.Kind {
	case String:
		return v.S, nil
	case Int:
		return v.I, nil
	case Float:
		return FormatFloat(v.F), nil
	case Bool:
		if v.B {
			return "True", nil
		}
		return "False", nil
	case Null:
		return "None", nil
	}
	return "", fmt.Errorf("not a scalar: %s", Compact(v, false))
}

// Parse reads exactly one JSON document.
func Parse(data []byte) (*Value, error) {
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.UseNumber()
	v, err := parseValue(dec)
	if err != nil {
		return nil, err
	}
	if _, err := dec.Token(); err != io.EOF {
		if err == nil {
			return nil, errors.New("extra data after the JSON document")
		}
		return nil, err
	}
	return v, nil
}

func parseValue(dec *json.Decoder) (*Value, error) {
	tok, err := dec.Token()
	if err != nil {
		return nil, err
	}
	switch t := tok.(type) {
	case nil:
		return NullValue(), nil
	case bool:
		return &Value{Kind: Bool, B: t}, nil
	case string:
		return Str(t), nil
	case json.Number:
		return parseNumber(string(t))
	case json.Delim:
		switch t {
		case '[':
			out := &Value{Kind: Array, A: []*Value{}}
			for dec.More() {
				x, err := parseValue(dec)
				if err != nil {
					return nil, err
				}
				out.A = append(out.A, x)
			}
			_, err := dec.Token() // ]
			return out, err
		case '{':
			o := NewObj()
			for dec.More() {
				kt, err := dec.Token()
				if err != nil {
					return nil, err
				}
				x, err := parseValue(dec)
				if err != nil {
					return nil, err
				}
				o.Set(kt.(string), x)
			}
			_, err := dec.Token() // }
			return ObjValue(o), err
		}
	}
	return nil, fmt.Errorf("unexpected token %v", tok)
}

func parseNumber(s string) (*Value, error) {
	if strings.ContainsAny(s, ".eE") {
		f, err := strconv.ParseFloat(s, 64)
		if err != nil && !errors.Is(err, strconv.ErrRange) {
			return nil, err
		}
		return Num(f), nil
	}
	n, ok := new(big.Int).SetString(s, 10)
	if !ok {
		return nil, fmt.Errorf("bad integer %q", s)
	}
	// Canonical text: "-0" reads as 0.
	return &Value{Kind: Int, I: n.String()}, nil
}

// FormatFloat prints f as the shortest text that reads back as f, with a
// decimal point or an exponent always present: fixed notation for a decimal
// exponent in [-4, 16), exponent notation outside it.
func FormatFloat(f float64) string {
	switch {
	case math.IsNaN(f):
		return "NaN"
	case math.IsInf(f, 1):
		return "Infinity"
	case math.IsInf(f, -1):
		return "-Infinity"
	}
	e := strconv.FormatFloat(f, 'e', -1, 64)
	exp, _ := strconv.Atoi(e[strings.IndexByte(e, 'e')+1:])
	if exp < -4 || exp >= 16 {
		return e
	}
	s := strconv.FormatFloat(f, 'f', -1, 64)
	if !strings.ContainsRune(s, '.') {
		s += ".0"
	}
	return s
}

// Round rounds f to n decimal places, correctly: to the nearest decimal of
// f's exact binary value, an exact tie going to the even digit.
func Round(f float64, n int) float64 {
	if math.IsNaN(f) || math.IsInf(f, 0) {
		return f
	}
	r, _ := strconv.ParseFloat(strconv.FormatFloat(f, 'f', n, 64), 64)
	return r
}

// Quote writes s as a JSON string.
func Quote(sb *strings.Builder, s string, ascii bool) {
	sb.WriteByte('"')
	for _, r := range s {
		switch r {
		case '"':
			sb.WriteString(`\"`)
		case '\\':
			sb.WriteString(`\\`)
		case '\n':
			sb.WriteString(`\n`)
		case '\r':
			sb.WriteString(`\r`)
		case '\t':
			sb.WriteString(`\t`)
		case '\b':
			sb.WriteString(`\b`)
		case '\f':
			sb.WriteString(`\f`)
		default:
			switch {
			case r < 0x20:
				fmt.Fprintf(sb, `\u%04x`, r)
			case !ascii || r <= '~':
				sb.WriteRune(r)
			case r > 0xFFFF:
				hi, lo := utf16.EncodeRune(r)
				fmt.Fprintf(sb, `\u%04x\u%04x`, hi, lo)
			default:
				fmt.Fprintf(sb, `\u%04x`, r)
			}
		}
	}
	sb.WriteByte('"')
}

// Compact prints v on one line with "," and ":" separators.
func Compact(v *Value, ascii bool) string {
	var sb strings.Builder
	write(&sb, v, format{item: ",", key: ":", ascii: ascii}, 0)
	return sb.String()
}

// Spaced prints v on one line with ", " and ": " separators.
func Spaced(v *Value, ascii bool) string {
	var sb strings.Builder
	write(&sb, v, format{item: ", ", key: ": ", ascii: ascii}, 0)
	return sb.String()
}

// Indented prints v with each element on its own line, indented by indent
// spaces per level, keys sorted when sortKeys is set.
func Indented(v *Value, indent int, sortKeys, ascii bool) string {
	var sb strings.Builder
	write(&sb, v, format{item: ",", key: ": ", ascii: ascii, indent: indent, multiline: true, sortKeys: sortKeys}, 0)
	return sb.String()
}

type format struct {
	item, key string
	ascii     bool
	indent    int
	multiline bool
	sortKeys  bool
}

func (f format) newline(sb *strings.Builder, level int) {
	if f.multiline {
		sb.WriteByte('\n')
		sb.WriteString(strings.Repeat(" ", f.indent*level))
	}
}

func write(sb *strings.Builder, v *Value, f format, level int) {
	if v == nil {
		sb.WriteString("null")
		return
	}
	switch v.Kind {
	case Null:
		sb.WriteString("null")
	case Bool:
		sb.WriteString(strconv.FormatBool(v.B))
	case Int:
		sb.WriteString(v.I)
	case Float:
		sb.WriteString(FormatFloat(v.F))
	case String:
		Quote(sb, v.S, f.ascii)
	case Array:
		if len(v.A) == 0 {
			sb.WriteString("[]")
			return
		}
		sb.WriteByte('[')
		for i, x := range v.A {
			if i > 0 {
				sb.WriteString(f.item)
			}
			f.newline(sb, level+1)
			write(sb, x, f, level+1)
		}
		f.newline(sb, level)
		sb.WriteByte(']')
	case Object:
		if v.O.Len() == 0 {
			sb.WriteString("{}")
			return
		}
		keys := v.O.Keys()
		if f.sortKeys {
			keys = append([]string(nil), keys...)
			sort.Strings(keys)
		}
		sb.WriteByte('{')
		for i, k := range keys {
			if i > 0 {
				sb.WriteString(f.item)
			}
			f.newline(sb, level+1)
			Quote(sb, k, f.ascii)
			sb.WriteString(f.key)
			x, _ := v.O.Get(k)
			write(sb, x, f, level+1)
		}
		f.newline(sb, level)
		sb.WriteByte('}')
	}
}
